#include "allheaders.h"
#include <stdio.h>
int main(void){PIX *m=pixCreate(200,200,8);for(int y=0;y<200;y++)for(int x=0;x<200;x++)pixSetPixel(m,x,y,20+L_ABS((100-y)*(100-x))/50);PIX *inv=pixInvert(NULL,m);int comparisons=0;for(int c=4;c<=8;c+=4)for(int k=0;k<2;k++)for(int mi=0;mi<2;mi++)for(int mode=0;mode<2;mode++){PIX *mask=mi?inv:m;PIX *a=pixCopy(NULL,m);pixAddConstantGray(a,k?60:-30);PIX *b=pixCopy(NULL,a);if(mode){pixSeedfillGrayInv(a,mask,c);pixSeedfillGrayInvSimple(b,mask,c);}else{pixSeedfillGray(a,mask,c);pixSeedfillGraySimple(b,mask,c);}int equal=0;pixEqual(a,b,&equal);if(!equal){printf("OLD_COMPARE_FAIL c=%d k=%d mi=%d mode=%d\n",c,k,mi,mode);return 1;}comparisons++;pixDestroy(&a);pixDestroy(&b);}printf("OLD_GRAYFILL_NUMERIC_COMPARISONS_OK count=%d\n",comparisons);pixDestroy(&m);pixDestroy(&inv);}
